cat << 'EOF' > test-ajv.ts
import Ajv from 'ajv';
const ajv = new Ajv({
  strict: false,
  validateFormats: false,
});
EOF
npx tsc --noEmit test-ajv.ts

cat << 'EOF' > patch.js
const fs = require('fs');
const path = 'src/orchestration/tools/registry.ts';
let code = fs.readFileSync(path, 'utf8');
code = code.replace(/import AjvMod from 'ajv';/, 'import Ajv from \'ajv\';');
code = code.replace(/const Ajv = [^\n]+\n/, '');
code = code.replace(/const ajv = new Ajv\(\{/, 'const ajv = new Ajv({\n  strict: false,\n  validateFormats: false\n} as any); //');
fs.writeFileSync(path, code);
EOF
node patch.js
npm run typecheck

cat << 'EOF' > patch.js
const fs = require('fs');
const path = 'src/orchestration/tools/registry.ts';
let code = fs.readFileSync(path, 'utf8');
const oldBlock = `    if (!validate(input)) {
      const error = validate.errors?.[0] as Record<string, unknown> | undefined;
      const params = error?.params as Record<string, unknown> | undefined;
      const instancePath =
        (error?.instancePath as string | undefined) ?? ((error as any)?.dataPath as string | undefined);
      const propPath = instancePath || (params?.missingProperty as string | undefined) || 'input';
      const expectedType = (params?.type as string | undefined) || 'required';
      return {result: \`Validation failed: \${propPath} is \${expectedType}\`};
    }`;
const newBlock = `    if (!validate(input)) {
      const err = validate.errors?.[0] as Record<string, unknown> | undefined;
      const params = err?.params as Record<string, unknown> | undefined;
      const prop = (err?.instancePath as string | undefined) || (err?.dataPath as string | undefined) || (params?.missingProperty as string | undefined) || 'input';
      return {result: \`Validation failed: \${prop} is \${(params?.type as string | undefined) || 'required'}\`};
    }`;
if (code.includes(oldBlock)) {
  code = code.replace(oldBlock, newBlock);
  fs.writeFileSync(path, code);
  console.log('patched');
} else {
  console.log('could not find block');
}
EOF
node patch.js
